public Yaf_View_InterfacenullfalseYaf_Dispatcher::initView stringtemplates_dir arraynulloptionsnull
Inicializa e retorna uma instância de Yaf_View_Simple associada ao despachante, usando o diretório de modelos fornecido.

&reftitle.returnvalues;

 Uma instância de Yaf_View_Interface em caso de
 sucesso, ou &false; / &null; em caso de falha.

  &reftitle.examples;

   Exemplo de Yaf_Dispatcher::initView


<?php
$app = new Yaf_Application(dirname(__FILE__) . "/conf/application.ini");

$view = Yaf_Dispatcher::getInstance()->initView(
    dirname(__FILE__) . "/application/views",
    array("tpl_suffix" => ".html")
);

$view->assign("title", "Home");
?>
